import abc
from numbers import Complex, Real, Rational, Integral, Number

def concretize(cls):

    def not_implemented(*args, **kwargs):
        raise NotImplementedError()
    for name in dir(cls):
        try:
            value = getattr(cls, name)
            if value.__isabstractmethod__:
                setattr(cls, name, not_implemented)
        except AttributeError:
            pass
    abc.update_abstractmethods(cls)
    return cls

def _t():

    class _SelfNS:
        pass
    self = _SelfNS()

    @concretize
    class MyComplex(Complex):

        def __init__(self, real, imag):
            self.r = real
            self.i = imag

        @property
        def real(self):
            return self.r

        @property
        def imag(self):
            return self.i

        def __add__(self, other):
            if isinstance(other, Complex):
                return MyComplex(self.imag + other.imag, self.real + other.real)
            raise NotImplementedError

        def __neg__(self):
            return MyComplex(-self.real, -self.imag)

        def __eq__(self, other):
            if isinstance(other, Complex):
                return self.imag == other.imag and self.real == other.real
            if isinstance(other, Number):
                return self.imag == 0 and self.real == other.real
    assert bool(MyComplex(1, 1)), ('assertTrue', bool(MyComplex(1, 1)))
    assert bool(MyComplex(0, 1)), ('assertTrue', bool(MyComplex(0, 1)))
    assert bool(MyComplex(1, 0)), ('assertTrue', bool(MyComplex(1, 0)))
    assert not bool(MyComplex(0, 0)), ('assertFalse', bool(MyComplex(0, 0)))
    assert MyComplex(2, 3) - complex(1, 2) == MyComplex(1, 1), ('assertEqual', MyComplex(2, 3) - complex(1, 2), MyComplex(1, 1))
    assert complex(2, 3) - MyComplex(1, 2) == MyComplex(1, 1), ('assertEqual', complex(2, 3) - MyComplex(1, 2), MyComplex(1, 1))
